  3	/*
  4	 * Boot VC Handler - This is the first VC handler during boot, there is no GHCB
  5	 * page yet, so it only supports the MSR based communication with the
  6	 * hypervisor and only the CPUID exit-code.
  7	 */
  8	void __init do_vc_no_ghcb(struct pt_regs *regs, unsigned long exit_code)
  9	{
 10		unsigned int fn = lower_bits(regs->ax, 32);
 11		unsigned long val;
 12	
 13		/* Only CPUID is supported via MSR protocol */
 14		if (exit_code != SVM_EXIT_CPUID)
 15			goto fail;
 16	
 17		sev_es_wr_ghcb_msr(GHCB_CPUID_REQ(fn, GHCB_CPUID_REQ_EAX));
 18		VMGEXIT();
 19		val = sev_es_rd_ghcb_msr();
 20		if (GHCB_SEV_GHCB_RESP_CODE(val) != GHCB_SEV_CPUID_RESP)
 21			goto fail;
 22		regs->ax = val >> 32;
 23	
 24		sev_es_wr_ghcb_msr(GHCB_CPUID_REQ(fn, GHCB_CPUID_REQ_EBX));
 25		VMGEXIT();
 26		val = sev_es_rd_ghcb_msr();
 27		if (GHCB_SEV_GHCB_RESP_CODE(val) != GHCB_SEV_CPUID_RESP)
 28			goto fail;
 29		regs->bx = val >> 32;
 30	
 31		sev_es_wr_ghcb_msr(GHCB_CPUID_REQ(fn, GHCB_CPUID_REQ_ECX));
 32		VMGEXIT();
 33		val = sev_es_rd_ghcb_msr();
 34		if (GHCB_SEV_GHCB_RESP_CODE(val) != GHCB_SEV_CPUID_RESP)
 35			goto fail;
 36		regs->cx = val >> 32;
 37	
 38		sev_es_wr_ghcb_msr(GHCB_CPUID_REQ(fn, GHCB_CPUID_REQ_EDX));
 39		VMGEXIT();
 40		val = sev_es_rd_ghcb_msr();
 41		if (GHCB_SEV_GHCB_RESP_CODE(val) != GHCB_SEV_CPUID_RESP)
 42			goto fail;
 43		regs->dx = val >> 32;
 44	
 45		/*
 46		 * This is a VC handler and the #VC is only raised when SEV-ES is
 47		 * active, which means SEV must be active too. Do sanity checks on the
 48		 * CPUID results to make sure the hypervisor does not trick the kernel
 49		 * into the no-sev path. This could map sensitive data unencrypted and
 50		 * make it accessible to the hypervisor.
 51		 *
 52		 * In particular, check for:
 53		 *	- Availability of CPUID leaf 0x8000001f
 54		 *	- SEV CPUID bit.
 55		 *
 56		 * The hypervisor might still report the wrong C-bit position, but this
 57		 * can't be checked here.
 58		 */
 59	
 60		if (fn == 0x80000000 && (regs->ax < 0x8000001f))
 61			/* SEV leaf check */
 62			goto fail;
 63		else if ((fn == 0x8000001f && !(regs->ax & BIT(1))))
 64			/* SEV bit */
 65			goto fail;
 66	
 67		/* Skip over the CPUID two-byte opcode */
 68		regs->ip += 2;
 69	
 70		return;
 71	
 72	fail:
 73		sev_es_wr_ghcb_msr(GHCB_SEV_TERMINATE);
 74		VMGEXIT();
 75	
 76		/* Shouldn't get here - if we do halt the machine */
 77		while (true)
 78			asm volatile("hlt\n");
 79	}
